<?php require_once __DIR__.'/includes/config.php';require_applicant();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=$_POST['loan_type']??'';$amount=(float)($_POST['amount']??0);$years=(int)($_POST['years']??0);$purpose=trim($_POST['purpose']??'');$allowed=['Personal Loan','Home Loan','Education Loan'];if(!in_array($type,$allowed,true)||$amount<1000||$amount>10000000||$years<1||$years>30||strlen($purpose)<5){$error='Please check all application details.';}else{$ref='LL-'.strtoupper(bin2hex(random_bytes(4)));$s=$pdo->prepare('INSERT INTO applications(reference_no,user_id,loan_type,amount,tenure_years,purpose) VALUES(?,?,?,?,?,?)');$s->execute([$ref,$_SESSION['user_id'],$type,$amount,$years,$purpose]);header('Location: dashboard.php?submitted='.urlencode($ref));exit;}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Apply | Ladle Loan</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="form-wrap"><form class="form-card" method="post"><a href="dashboard.php">← Dashboard</a><h1>Loan application</h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Loan type<select name="loan_type" required><option>Personal Loan</option><option>Home Loan</option><option>Education Loan</option></select></label><label>Amount (₹)<input type="number" name="amount" min="1000" max="10000000" required></label><label>Tenure (years)<input type="number" name="years" min="1" max="30" required></label><label>Purpose<textarea name="purpose" minlength="5" maxlength="500" required></textarea></label><button class="btn">Submit application</button><p><small>Demo project: do not submit real financial or identity information.</small></p></form></div></body></html>